/** The subset of frontmatter fields relevant to the skills/resources convention */
export interface Frontmatter {
    name?: string;
    description?: string;
}
/**
 * Parses the optional leading YAML frontmatter block of a markdown file.
 * @param content Raw file content
 * @returns The parsed `name`/`description` fields, or an empty object when there is no frontmatter block
 * @throws if a frontmatter block is present but contains malformed YAML
 */
export declare function parseFrontmatter(content: string): Frontmatter;
